-- Etapa 6C. Compra 2017; UF do pedido SP; todos os status. Executar READ ONLY.
WITH p AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pedidos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),i AS (SELECT x.*,c.dia,c.mes FROM gold.fato_itens_pedido x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP'),g AS (SELECT x.*,c.dia,c.mes FROM gold.fato_pagamentos x LEFT JOIN gold.dim_calendario c ON c.data_sk=x.data_compra_sk LEFT JOIN gold.dim_localizacao l ON l.localizacao_sk=x.localizacao_sk WHERE c.ano=2017 AND l.customer_state='SP') , a AS (SELECT i.vendedor_sk,d.seller_id,d.membro_tipo,'Vendedor '||i.vendedor_sk rotulo,count(*) itens,sum(i.price) price,sum(i.freight_value) freight_value FROM i LEFT JOIN gold.dim_vendedores d ON d.vendedor_sk=i.vendedor_sk GROUP BY 1,2,3) SELECT rank() OVER(ORDER BY price DESC NULLS LAST) posicao,a.* FROM a ORDER BY price DESC NULLS LAST,vendedor_sk;
